[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* ===== CSS Variables & Reset ===== */
:root {
  --primary: #F02D00;
  --primary-hover: #d42800;
  --dark: #171717;
  --dark-light: #2a2a2a;
  --white: #FFFFFF;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-300: #d1d5db;
  --gray-400: #9ca3af;
  --gray-500: #6b7280;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-800: #1f2937;
  --teal: #00BFA6;
  --teal-dark: #009e8a;
  --green: #10B981;
  --yellow: #F59E0B;
  --radius: 12px;
  --radius-sm: 8px;
  --radius-lg: 16px;
  --shadow: 0 1px 3px rgba(0,0,0,.1), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 6px rgba(0,0,0,.07), 0 2px 4px rgba(0,0,0,.06);
  --shadow-lg: 0 10px 15px rgba(0,0,0,.1), 0 4px 6px rgba(0,0,0,.05);
  --shadow-xl: 0 20px 25px rgba(0,0,0,.1), 0 10px 10px rgba(0,0,0,.04);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --transition: .2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
body { font-family: var(--font); color: var(--dark); background: var(--white); line-height: 1.6; }
a { text-decoration: none; color: inherit; }
ul, ol { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input { font-family: inherit; }

/* ===== Utility ===== */
.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

/* ===== Promo Banner ===== */
.promo-banner {
  background: var(--dark);
  color: var(--white);
  padding: 10px 24px;
  text-align: center;
  font-size: 14px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
}
.promo-banner .countdown { color: var(--primary); font-weight: 700; font-size: 15px; }
.promo-banner .close-btn {
  position: absolute; right: 16px; top: 50%; transform: translateY(-50%);
  color: var(--gray-400); font-size: 18px; padding: 4px 8px; border-radius: 4px;
}
