  position: sticky; top: 0; z-index: 100;
}
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px; height: 64px; max-width: 1280px; margin: 0 auto;
}
.logo { font-size: 22px; font-weight: 800; color: var(--dark); letter-spacing: -0.5px; }
.logo span { color: var(--primary); }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a { font-size: 15px; font-weight: 500; color: var(--gray-600); transition: color var(--transition); }
.nav-links a:hover { color: var(--dark); }
.nav-links a.active { color: var(--dark); font-weight: 600; }
.header-actions { display: flex; align-items: center; gap: 16px; }
.search-btn { color: var(--gray-500); padding: 8px; border-radius: var(--radius-sm); }
.search-btn:hover { background: var(--gray-100); color: var(--dark); }
.btn { display: inline-flex; align-items: center; justify-content: center; padding: 10px 20px; border-radius: 50px; font-weight: 600; font-size: 14px; transition: all var(--transition); }
.btn-outline { border: 1.5px solid var(--gray-300); color: var(--dark); }
.btn-outline:hover { border-color: var(--dark); background: var(--gray-50); }
.btn-primary { background: var(--primary); color: var(--white); }
.btn-primary:hover { background: var(--primary-hover); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-dark { background: var(--dark); color: var(--white); }
.btn-dark:hover { background: var(--dark-light); }
.btn-teal { background: var(--teal); color: var(--white); }
.btn-teal:hover { background: var(--teal-dark); }
.btn-lg { padding: 14px 32px; font-size: 16px; }

/* Mobile menu */
.menu-toggle { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.menu-toggle span { display: block; width: 22px; height: 2px; background: var(--dark); border-radius: 2px; transition: var(--transition); }

/* ===== Hero Carousel ===== */
.hero-carousel { position: relative; background: var(--dark); overflow: hidden; }
.hero-carousel .slides { display: flex; transition: transform .5s cubic-bezier(.4,0,.2,1); }
.hero-carousel .slide {
  min-width: 100%; display: flex; align-items: center;
  padding: 60px 0; position: relative;
}
.hero-carousel .slide-content {
  max-width: 1280px; margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center; gap: 60px; width: 100%;
}
.hero-carousel .slide-text { flex: 1; color: var(--white); }
.hero-carousel .slide-text .badge {
  display: inline-flex; align-items: center; gap: 6px;
  background: rgba(255,255,255,.12); color: var(--teal);
