.hero-carousel .slide-meta span { font-size: 14px; color: var(--gray-400); display: flex; align-items: center; gap: 6px; }
.hero-carousel .slide-meta .rating { color: var(--green); font-weight: 600; }
.hero-carousel .slide-pricing { display: flex; align-items: center; gap: 16px; }
.hero-carousel .slide-pricing .original { text-decoration: line-through; color: var(--gray-500); font-size: 18px; }
.hero-carousel .slide-pricing .sale { font-size: 32px; font-weight: 800; color: var(--white); }
.hero-carousel .slide-pricing .discount-badge {
  background: var(--primary); color: var(--white);
  padding: 4px 10px; border-radius: 6px; font-size: 13px; font-weight: 700;
}
.hero-carousel .slide-pricing .free-badge {
  background: var(--teal); color: var(--white);
  padding: 6px 14px; border-radius: 50px; font-size: 13px; font-weight: 700;
}
.hero-carousel .slide-image {
  flex: 1; max-width: 500px; aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--dark-light) 0%, rgba(240,45,0,.15) 100%);
  border-radius: var(--radius-lg); display: flex; align-items: center; justify-content: center;
  font-size: 64px; color: rgba(255,255,255,.2);
}
.carousel-nav {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%; background: rgba(255,255,255,.15);
  color: var(--white); font-size: 20px; display: flex; align-items: center; justify-content: center;
  backdrop-filter: blur(4px); transition: all var(--transition); z-index: 5;
}
.carousel-nav:hover { background: rgba(255,255,255,.3); }
.carousel-nav.prev { left: 24px; }
.carousel-nav.next { right: 24px; }
.carousel-dots {
  display: flex; justify-content: center; gap: 8px;
  padding: 16px 0 24px; position: absolute; bottom: 0; left: 50%; transform: translateX(-50%);
}
.carousel-dots .dot {
  width: 10px; height: 10px; border-radius: 50%; background: rgba(255,255,255,.3);
  transition: all var(--transition); cursor: pointer;
}
.carousel-dots .dot.active { background: var(--white); width: 28px; border-radius: 5px; }

/* ===== Section Titles ===== */
.section-title {
  font-size: 28px; font-weight: 800; color: var(--dark); margin-bottom: 8px;
}
.section-subtitle { font-size: 16px; color: var(--gray-500); margin-bottom: 32px; }

/* ===== Course Card ===== */
.course-card {
  background: var(--white); border-radius: var(--radius); overflow: hidden;
  box-shadow: var(--shadow); transition: all .3s ease; position: relative;
}
