  font-size: 40px; color: var(--gray-300);
}
.card-image .placeholder-img.bg-1 { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: rgba(255,255,255,.4); }
.card-image .placeholder-img.bg-2 { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); color: rgba(255,255,255,.4); }
.card-image .placeholder-img.bg-3 { background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); color: rgba(255,255,255,.4); }
.card-image .placeholder-img.bg-4 { background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%); color: rgba(255,255,255,.4); }
.card-image .placeholder-img.bg-5 { background: linear-gradient(135deg, #fa709a 0%, #fee140 100%); color: rgba(255,255,255,.4); }
.card-image .placeholder-img.bg-6 { background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%); color: rgba(255,255,255,.4); }
.course-card .bestseller-badge {
  position: absolute; top: 12px; left: 12px;
  background: var(--yellow); color: var(--dark); font-size: 11px; font-weight: 700;
