.course-card .card-instructor { font-size: 13px; color: var(--gray-500); margin-bottom: 10px; }
.course-card .card-stats { display: flex; align-items: center; gap: 12px; font-size: 13px; color: var(--gray-500); margin-bottom: 10px; }
.course-card .card-stats .rating-val { color: var(--green); font-weight: 600; }
