.filter-select:focus { outline: none; border-color: var(--primary); }
.masonry-grid {
  columns: 4; column-gap: 20px; padding-bottom: 60px;
}
.project-card {
  break-inside: avoid; margin-bottom: 20px; border-radius: var(--radius);
  overflow: hidden; background: var(--white); box-shadow: var(--shadow);
  transition: all .3s ease; cursor: pointer;
}
.project-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-lg); }
.project-card .project-image {
  width: 100%; display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,.3); font-size: 48px;
}
.project-card .project-image.h-sm { height: 180px; }
.project-card .project-image.h-md { height: 240px; }
.project-card .project-image.h-lg { height: 320px; }
.project-card .project-image.h-xl { height: 400px; }
.project-card .project-info { padding: 14px 16px; }
.project-card .project-title { font-size: 14px; font-weight: 700; margin-bottom: 4px; }
.project-card .project-user { font-size: 12px; color: var(--gray-500); margin-bottom: 8px; }
.project-card .project-stats { display: flex; gap: 12px; font-size: 12px; color: var(--gray-400); }
.project-card .winner-badge {
  position: absolute; top: 12px; left: 12px;
  background: var(--yellow); color: var(--dark); font-size: 11px; font-weight: 700;
  padding: 4px 10px; border-radius: 4px;
}

/* ===== Plus Page ===== */
.plus-hero {
  background: linear-gradient(135deg, var(--dark) 0%, #1a1a2e 50%, #16213e 100%);
  color: var(--white); padding: 80px 0; text-align: center;
}
.plus-hero h1 { font-size: 48px; font-weight: 800; margin-bottom: 16px; line-height: 1.1; }
.plus-hero .tagline { font-size: 20px; color: var(--gray-300); margin-bottom: 32px; max-width: 600px; margin-left: auto; margin-right: auto; }
.plus-hero .cta-group { display: flex; gap: 16px; justify-content: center; }

/* Pricing Toggle */
.pricing-section { padding: 80px 0; text-align: center; }
.pricing-toggle {
  display: inline-flex; background: var(--gray-100); border-radius: 50px;
  padding: 4px; margin-bottom: 40px;
}
.pricing-toggle .toggle-btn {
  padding: 12px 28px; border-radius: 50px; font-size: 15px; font-weight: 600;
  color: var(--gray-500); transition: all var(--transition); position: relative;
}
.pricing-toggle .toggle-btn.active { background: var(--dark); color: var(--white); }
.pricing-toggle .toggle-btn .save-badge {
  position: absolute; top: -10px; right: -10px;
  background: var(--primary); color: var(--white); font-size: 10px; font-weight: 700;
  padding: 3px 8px; border-radius: 50px;
}
.pricing-cards { display: flex; gap: 24px; justify-content: center; max-width: 800px; margin: 0 auto; }
.pricing-card {
  flex: 1; max-width: 380px; background: var(--white); border: 2px solid var(--gray-200);
  border-radius: var(--radius-lg); padding: 32px; text-align: left; position: relative;
  transition: all var(--transition);
}
.pricing-card.featured { border-color: var(--primary); box-shadow: var(--shadow-xl); }
.pricing-card.featured .recommended-badge {
  position: absolute; top: -14px; left: 50%; transform: translateX(-50%);
  background: var(--primary); color: var(--white); font-size: 12px; font-weight: 700;
  padding: 4px 16px; border-radius: 50px; white-space: nowrap;
}
.pricing-card .plan-name { font-size: 14px; font-weight: 600; color: var(--gray-500); text-transform: uppercase; letter-spacing: .5px; margin-bottom: 8px; }
.pricing-card .plan-price { font-size: 40px; font-weight: 800; color: var(--dark); margin-bottom: 4px; }
.pricing-card .plan-price span { font-size: 16px; font-weight: 500; color: var(--gray-500); }
.pricing-card .plan-billing { font-size: 14px; color: var(--gray-500); margin-bottom: 24px; }
.pricing-card .plan-features { margin-bottom: 24px; }
.pricing-card .plan-features li { display: flex; align-items: flex-start; gap: 10px; font-size: 14px; color: var(--gray-600); padding: 8px 0; }
.pricing-card .plan-features li .check { color: var(--green); font-weight: 700; flex-shrink: 0; }

/* Plus Benefits */
.benefits-section { padding: 80px 0; background: var(--gray-50); }
.benefits-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 24px; margin-top: 40px; }
.benefit-card {
  background: var(--white); border-radius: var(--radius); padding: 32px;
  box-shadow: var(--shadow); transition: all .3s ease;
}
.benefit-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-lg); }
.benefit-card .benefit-icon {
  width: 56px; height: 56px; border-radius: var(--radius-sm);
  background: linear-gradient(135deg, rgba(240,45,0,.1), rgba(0,191,166,.1));
  display: flex; align-items: center; justify-content: center;
  font-size: 24px; margin-bottom: 16px;
}
.benefit-card h3 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
.benefit-card p { font-size: 14px; color: var(--gray-500); line-height: 1.6; }

/* FAQ Accordion */
.faq-section { padding: 80px 0; }
.faq-list { max-width: 720px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; padding: 20px 0; font-size: 16px; font-weight: 600;
  color: var(--dark); text-align: left;
}
.faq-question .faq-icon { font-size: 20px; color: var(--gray-400); transition: transform .3s; flex-shrink: 0; margin-left: 16px; }
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height .3s ease, padding .3s ease; }
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer p { padding: 0 0 20px; font-size: 15px; color: var(--gray-500); line-height: 1.7; }

/* Plus Catalog Carousel */
.plus-catalog-section { padding: 60px 0; }
.plus-credits-section { padding: 60px 0; background: var(--gray-50); }

/* ===== Login Page ===== */
.login-page { min-height: 100vh; display: flex; align-items: center; justify-content: center; background: var(--gray-50); padding: 40px 24px; }
.login-card {
  width: 100%; max-width: 420px; background: var(--white); border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl); padding: 48px 40px;
}
.login-card .login-logo { text-align: center; margin-bottom: 32px; }
.login-card .login-logo .logo { font-size: 26px; }
.login-card h1 { font-size: 28px; font-weight: 800; margin-bottom: 8px; }
.login-card .login-subtitle { font-size: 15px; color: var(--gray-500); margin-bottom: 32px; }
.social-btn {
  display: flex; align-items: center; justify-content: center; gap: 10px;
  width: 100%; padding: 12px; border-radius: var(--radius-sm);
  font-size: 14px; font-weight: 600; margin-bottom: 12px;
  border: 1px solid var(--gray-200); transition: all var(--transition);
}
.social-btn:hover { background: var(--gray-50); border-color: var(--gray-300); }
.social-btn.facebook { background: #1877F2; color: var(--white); border-color: #1877F2; }
.social-btn.facebook:hover { background: #166fe5; }
.social-btn.apple { background: var(--dark); color: var(--white); border-color: var(--dark); }
.social-btn.apple:hover { background: var(--dark-light); }
.divider { display: flex; align-items: center; gap: 16px; margin: 24px 0; }
.divider::before, .divider::after { content: ''; flex: 1; height: 1px; background: var(--gray-200); }
.divider span { font-size: 13px; color: var(--gray-400); white-space: nowrap; }
.form-group { margin-bottom: 16px; }
.form-group label { display: block; font-size: 13px; font-weight: 600; color: var(--gray-700); margin-bottom: 6px; }
.form-group .input-wrapper { position: relative; }
.form-group input[type="email"],
.form-group input[type="password"],
.form-group input[type="text"] {
  width: 100%; padding: 12px 16px; border: 1.5px solid var(--gray-200); border-radius: var(--radius-sm);
  font-size: 15px; transition: all var(--transition);
}
.form-group input:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 3px rgba(240,45,0,.1); }
.password-toggle {
  position: absolute; right: 12px; top: 50%; transform: translateY(-50%);
  color: var(--gray-400); font-size: 18px; padding: 4px;
}
.password-toggle:hover { color: var(--gray-600); }
.forgot-link { display: block; text-align: right; font-size: 13px; color: var(--primary); margin-top: 8px; font-weight: 500; }
.forgot-link:hover { text-decoration: underline; }
.login-submit { width: 100%; margin-top: 24px; padding: 14px; font-size: 16px; }
.signup-link { text-align: center; margin-top: 24px; font-size: 14px; color: var(--gray-500); }
.signup-link a { color: var(--primary); font-weight: 600; }
.signup-link a:hover { text-decoration: underline; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .carousel-track .course-card { min-width: calc(33.333% - 14px); }
  .masonry-grid { columns: 3; }
  .courses-layout { grid-template-columns: 220px 1fr; }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .menu-toggle { display: flex; }
  .hero-carousel .slide-content { flex-direction: column; gap: 32px; padding: 0 24px; }
  .hero-carousel .slide-text h2 { font-size: 26px; }
  .hero-carousel .slide-image { max-width: 100%; }
  .carousel-track .course-card { min-width: calc(50% - 10px); }
  .masonry-grid { columns: 2; }
  .courses-layout { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .pricing-cards { flex-direction: column; align-items: center; }
  .pricing-card { max-width: 100%; }
  .value-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-col ul { display: none; }
  .footer-col.open ul { display: block; }
  .footer-col h4 .toggle-icon { display: inline; }
  .footer-col.open h4 .toggle-icon { transform: rotate(180deg); }
  .plus-hero h1 { font-size: 32px; }
  .plus-hero .cta-group { flex-direction: column; align-items: center; }
  .projects-filters { gap: 8px; }
  .filter-select { min-width: 120px; flex: 1; }
  .benefits-grid { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .carousel-track .course-card { min-width: calc(100% - 0px); }
  .masonry-grid { columns: 1; }
  .footer-grid { grid-template-columns: 1fr; }
  .course-grid { grid-template-columns: 1fr; }
  .promo-banner { font-size: 12px; padding: 10px 40px 10px 16px; }
}
